"use client";

import {
    Search,
    Filter,
    Download,
    MoreHorizontal,
    FileText,
    Clock,
    CheckCircle2,
    XCircle,
    Calendar,
    User,
    Plus
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useState } from "react";
import { useSimulation } from "@/components/SimulationProvider";
import useSWR, { mutate } from "swr";
import { fetcher } from "@/lib/fetcher";
import OrderJourneyModal from "@/components/OrderJourneyModal";
import axios from "axios";

export default function CertificatesPage() {
    const { currentUser } = useSimulation();
    const { data: certificates, error } = useSWR(`/api/certificates?seller=${currentUser.role === 'admin' ? 'admin' : currentUser.name}`, fetcher);
    const { data: products } = useSWR("/api/sales", fetcher);

    const [searchTerm, setSearchTerm] = useState("");
    const [statusFilter, setStatusFilter] = useState("Todos");
    const [isJourneyOpen, setIsJourneyOpen] = useState(false);

    const filteredCertificates = (certificates || []).filter((cert: any) => {
        const matchesSearch = cert.holder.toLowerCase().includes(searchTerm.toLowerCase()) ||
            cert.doc.includes(searchTerm) ||
            cert.protocol.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesStatus = statusFilter === "Todos" || cert.status === statusFilter;
        return matchesSearch && matchesStatus;
    });

    const handleOrderSubmit = async (data: any) => {
        try {
            const selectedProduct = products.find((p: any) => p.id === data.productId);
            const submissionData = {
                ...data,
                product: selectedProduct?.name,
                category: selectedProduct?.category,
                origin: `Venda Direta - Vendedor ${currentUser.name}`
            };

            const response = await axios.post("/api/integracao/vendas", submissionData);

            if (response.data.success) {
                alert(response.data.message);
                setIsJourneyOpen(false);
                mutate(`/api/certificates?seller=${currentUser.role === 'admin' ? 'admin' : currentUser.name}`);
            }
        } catch (error: any) {
            alert(error.response?.data?.error || "Ops! Algo deu errado na emissão.");
        }
    };

    return (
        <div className="p-4 lg:p-8 space-y-6">
            {/* Page Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-black mb-1">Certificados</h1>
                    <p className="text-xs text-slate-500 font-medium uppercase tracking-wider">Gestão de Pedidos e Emissões</p>
                </div>
                <button
                    onClick={() => setIsJourneyOpen(true)}
                    className="bg-primary text-white px-6 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 shadow-lg shadow-primary/20 hover:scale-[1.02] transition-all self-start md:self-auto"
                >
                    <Plus size={16} />
                    Novo Pedido
                </button>
            </div>

            {/* Filters Card */}
            <div className="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-800 p-4 shadow-sm">
                <div className="flex flex-col lg:flex-row gap-4">
                    <div className="relative flex-1">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input
                            type="text"
                            placeholder="Buscar por titular, CPF/CNPJ ou protocolo..."
                            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <div className="flex flex-wrap gap-2">
                        {["Todos", "Pago", "Pendente", "Cancelado"].map((status) => (
                            <button
                                key={status}
                                onClick={() => setStatusFilter(status)}
                                className={cn(
                                    "px-4 py-2 rounded-xl text-xs font-bold transition-all border",
                                    statusFilter === status
                                        ? "bg-primary text-white border-primary shadow-md shadow-primary/10"
                                        : "bg-white dark:bg-slate-800 text-slate-500 border-slate-200 dark:border-slate-700 hover:border-primary"
                                )}
                            >
                                {status}
                            </button>
                        ))}
                    </div>
                    <button className="lg:ml-auto px-4 py-2 bg-slate-100 dark:bg-slate-700 hover:bg-slate-200 rounded-xl text-xs font-bold transition-all flex items-center gap-2">
                        <Filter size={16} />
                        Filtros Avançados
                    </button>
                </div>
            </div>

            {/* Table Card */}
            <div className="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
                <div className="overflow-x-auto custom-scrollbar">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="border-b border-slate-100 dark:border-slate-800">
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 tracking-wider">Titular / Documento</th>
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 tracking-wider">Produto / Protocolo</th>
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 tracking-wider">Status</th>
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 tracking-wider">Data</th>
                                <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 tracking-wider text-right">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
                            {!certificates && !error && (
                                <tr>
                                    <td colSpan={5} className="px-6 py-10 text-center text-slate-400 text-xs italic">Carregando certificados...</td>
                                </tr>
                            )}
                            {filteredCertificates.map((cert: any) => (
                                <tr key={cert.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-900/50 transition-colors group">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-3">
                                            <div className="size-8 rounded-lg bg-primary/10 flex items-center justify-center text-primary">
                                                <User size={14} />
                                            </div>
                                            <div>
                                                <p className="text-sm font-bold text-slate-900 dark:text-white">{cert.holder}</p>
                                                <p className="text-[10px] text-slate-500 font-medium">{cert.doc}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <p className="text-sm font-medium text-slate-700 dark:text-slate-300">{cert.product}</p>
                                        <p className="text-[10px] text-slate-400 font-mono tracking-tighter">{cert.protocol}</p>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={cn(
                                            "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold ring-1 ring-inset",
                                            cert.status === 'Pago' ? "bg-emerald-50 text-emerald-700 ring-emerald-600/20 dark:bg-emerald-400/10 dark:text-emerald-400" :
                                                cert.status === 'Pendente' ? "bg-amber-50 text-amber-700 ring-amber-600/20 dark:bg-amber-400/10 dark:text-amber-400" :
                                                    "bg-rose-50 text-rose-700 ring-rose-600/20 dark:bg-rose-400/10 dark:text-rose-400"
                                        )}>
                                            {cert.status === 'Pago' && <CheckCircle2 size={10} />}
                                            {cert.status === 'Pendente' && <Clock size={10} />}
                                            {cert.status === 'Cancelado' && <XCircle size={10} />}
                                            {cert.status}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2 text-slate-500">
                                            <Calendar size={12} />
                                            <span className="text-xs font-medium">{cert.date}</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-lg text-slate-400 transition-colors">
                                            <MoreHorizontal size={18} />
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
                <div className="px-6 py-4 bg-slate-50 dark:bg-slate-900/50 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between">
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">Mostrando 3 de 48 resultados</p>
                    <div className="flex gap-1">
                        <button className="px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-700 text-xs font-bold disabled:opacity-50" disabled>Anterior</button>
                        <button className="px-3 py-1.5 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-xs font-bold">Próxima</button>
                    </div>
                </div>
            </div>
            <OrderJourneyModal
                isOpen={isJourneyOpen}
                onClose={() => setIsJourneyOpen(false)}
                onSubmit={handleOrderSubmit}
                products={products || []}
            />
        </div>
    );
}
